
use anyhow::{Result, bail}; use std::fs; use std::path::Path; use chrono::Utc; #[derive(Debug, Clone)] pub struct D2PMetadata { pub version: u32, pub filename: String, pub extension: String, pub file_type: u8, pub original_size: u64, pub compressed_size: u64, pub created_at: i64, pub modified_at: i64, pub checksum: u32, pub compression_preset: u8, pub flags: u8, } impl D2PMetadata { pub fn from_file(path: &Path) -> Result<Self> { let meta = fs::metadata(path)?; let filename = path.file_stem().unwrap_or_default().to_string_lossy().to_string(); let extension = path.extension().unwrap_or_default().to_string_lossy().to_string(); let data = fs::read(path)?; Ok(Self { version: 1, filename, extension, file_type: 0, original_size: data.len() as u64, compressed_size: 0, created_at: meta.created().map(|t| t.duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() as i64).unwrap_or(Utc::now().timestamp()), modified_at: meta.modified().map(|t| t.duration_since(std::time::UNIX_EPOCH).unwrap().as_secs() as i64).unwrap_or(Utc::now().timestamp()), checksum: crc32fast::hash(&data), compression_preset: 9, flags: 0x01, }) } pub fn to_bytes(&self) -> Vec<u8> { let mut buf = Vec::new(); buf.extend_from_slice(b"D2P\x00"); buf.extend_from_slice(&self.version.to_le_bytes()); let fname = self.filename.as_bytes(); buf.extend_from_slice(&(fname.len() as u16).to_le_bytes()); buf.extend_from_slice(fname); let ext = self.extension.as_bytes(); buf.push(ext.len() as u8); buf.extend_from_slice(ext); buf.push(self.file_type); buf.extend_from_slice(&self.original_size.to_le_bytes()); buf.extend_from_slice(&self.compressed_size.to_le_bytes()); buf.extend_from_slice(&self.created_at.to_le_bytes()); buf.extend_from_slice(&self.modified_at.to_le_bytes()); buf.extend_from_slice(&self.checksum.to_le_bytes()); buf.push(self.compression_preset); buf.push(self.flags); buf } pub fn from_bytes(data: &[u8]) -> Result<(Self, usize)> { if data.len() < 4 || &data[0..4] != b"D2P\x00" { bail!("Invalid D2P Magic Number"); } let mut off = 4; let version = u32::from_le_bytes(data[off..off+4].try_into()?); off += 4; let flen = u16::from_le_bytes(data[off..off+2].try_into()?) as usize; off += 2; let filename = String::from_utf8(data[off..off+flen].to_vec())?; off += flen; let elen = data[off] as usize; off += 1; let extension = String::from_utf8(data[off..off+elen].to_vec())?; off += elen; let file_type = data[off]; off += 1; let original_size = u64::from_le_bytes(data[off..off+8].try_into()?); off += 8; let compressed_size = u64::from_le_bytes(data[off..off+8].try_into()?); off += 8; let created_at = i64::from_le_bytes(data[off..off+8].try_into()?); off += 8; let modified_at = i64::from_le_bytes(data[off..off+8].try_into()?); off += 8; let checksum = u32::from_le_bytes(data[off..off+4].try_into()?); off += 4; let compression_preset = data[off]; off += 1; let flags = data[off]; off += 1; Ok((Self { version, filename, extension, file_type, original_size, compressed_size, created_at, modified_at, checksum, compression_preset, flags }, off)) } }